function renderRecordEditor(collection){
 if(collection.startsWith('officeFin')||collection==='officeBudget'||collection==='officeMonthlyClose'){if(!financeAllowed())return ''}
 const cfg=editableRecords[collection],rows=s[collection]||[];
 const selected=rows.find(x=>x.id===window.recordEditId&&window.recordEditCollection===collection)||{};
 const fieldNames=[...new Set([...cfg.fields,...rows.flatMap(row=>Object.keys(row).filter(name=>!['id','source','updatedBy'].includes(name)))] )];const fields=fieldNames.map(name=>{if(collection==='officeActions'&&name==='Responsável')return '<label>Responsável pela ação<select name="Responsável" required><option value="">Selecione</option>'+options([...new Set(['Ana Paula','Euler','Laís','Marlene',selected[name]].filter(Boolean))],selected[name])+'</select></label>';let monetary=['Valor','Entrada','Saída','Orçado mensal','Realizado no mês','Receitas previstas','Receitas recebidas','Despesas previstas','Despesas pagas','Resultado realizado','A receber','A pagar','Vencidos a receber','Faturamento comercial','Comissão apurada','Margem operacional','Variação R$','Variação %'].includes(name),type=['Vencimento','Prazo','Data','Data abertura','Data conclusão'].includes(name)?'date':'text';return '<label>'+esc(name)+'<input name="'+esc(name)+'" type="'+type+'" '+(monetary?'inputmode="decimal" placeholder="4.000,00" ':'')+'value="'+esc(monetary&&selected[name]!==undefined?formatBRLInput(selected[name]):selected[name]??'')+'"></label>'}).join('');
 return '<div class="box"><h3>'+(selected.id?'Editar registro':'Novo registro')+'</h3><p class="muted">As alterações ficam pendentes até a sincronização com a nuvem.</p><form id="recordForm" data-collection="'+collection+'"><div class="row">'+fields+'</div><button type="submit">Salvar alterações</button> <button type="button" class="secondary" onclick="clearRecordEditor()">Novo / limpar</button></form></div><div class="box"><h3>Registros existentes</h3>'+(rows.length?'<div class="scroll"><table><tr><th>Registro</th><th>Ações</th></tr>'+rows.map((x,i)=>'<tr><td>'+esc(x['Descrição']||x['Demanda ou problema']||x['Demanda']||x.Processo||x.Categoria||x['Mês']||x.ID||('Registro '+(i+1)))+'</td><td><button type="button" onclick="editRecord(\''+collection+'\','+i+')">Editar</button> <button type="button" class="secondary" onclick="deleteEntity(\''+cfg.kind+'\',\''+esc(x.id)+'\')">Excluir</button></td></tr>').join('')+'</table></div>':'Nenhum registro cadastrado.')+'</div>';
}
function changeOfficeActionOwner(id,name){const action=(s.officeActions||[]).find(x=>x.id===id);if(!action||!name)return;action['Responsável']=name;action['Atualizado por']=s.user;action['Última atualização']=new Date().toISOString();queue('office_action',action);render()}
function editRecord(collection,index){
 const row=(s[collection]||[])[index];if(!row)return;
 window.recordEditCollection=collection;window.recordEditId=row.id||'';
 if(!row.id){row.id=uid();save();window.recordEditId=row.id}
 render();$('recordForm')?.scrollIntoView({behavior:'smooth',block:'start'});
}
function clearRecordEditor(){window.recordEditId='';window.recordEditCollection='';render()}
function saveRecord(e){
 e.preventDefault();const collection=e.target.dataset.collection,cfg=editableRecords[collection];
 if(!cfg||(collection==='officeFinance'||collection==='officeBudget'||collection==='officeMonthlyClose')&&!financeAllowed())return;
 const data=Object.fromEntries(new FormData(e.target));
 for(const name of ['Valor','Entrada','Saída','Orçado mensal','Realizado no mês','Receitas previstas','Receitas recebidas','Despesas previstas','Despesas pagas','Resultado realizado','A receber','A pagar','Vencidos a receber','Faturamento comercial','Comissão apurada','Margem operacional','Variação R$','Variação %'])if(name in data){let v=data[name].trim()===''?0:parseBRLCents(data[name])/100;if(!Number.isFinite(v)||v<0){alert('Informe um valor válido para '+name);return}data[name]=v}
 const existing=(s[collection]||[]).find(x=>x.id===window.recordEditId);
 const merged={...(existing||{}),...data,id:existing?.id||uid()};
 const i=(s[collection]||[]).findIndex(x=>x.id===merged.id);
 if(i<0)s[collection].push(merged);else s[collection][i]=merged;
 queue(cfg.kind,merged);window.recordEditId='';window.recordEditCollection='';render();
}
const entityCollections={whatsapp_template:'whatsappTemplates',client:'clients',visit:'visits',order:'orders',task:'tasks',route:'routes',goal:'goals',price:'prices',commission_rate:'commissionRates',commission_receipt:'commissionReceipts',office_process:'officeProcesses',office_action:'officeActions',office_commercial:'officeCommercial',office_administrative:'officeAdministrative',office_ritual:'officeRituals',office_role:'officeRoles',office_finance:'officeFinance',office_budget:'officeBudget',office_monthly_close:'officeMonthlyClose'};
