function prefill(id){window.prefillId=id;show('registro')}
function priceCents(value){let n=Number(String(value??0).replace(',','.'));return Number.isFinite(n)?Math.round(n*100):0}
function parseBRLCents(value){let t=String(value??'').trim().replace(/^R\$\s*/i,'').replace(/\s/g,'');if(!t)return NaN;let whole,decimal='';if(t.includes(',')){let parts=t.split(',');if(parts.length!==2||!/^\d{1,3}(?:\.\d{3})*$|^\d+$/.test(parts[0])||!/^\d{1,2}$/.test(parts[1]))return NaN;whole=parts[0].replace(/\./g,'');decimal=parts[1]}else if(/^\d{1,3}(?:\.\d{3})+$/.test(t)){whole=t.replace(/\./g,'')}else if(/^\d+(?:\.\d{1,2})?$/.test(t)){let parts=t.split('.');whole=parts[0];decimal=parts[1]||''}else return NaN;let cents=Number(whole)*100+Number(decimal.padEnd(2,'0'));return Number.isSafeInteger(cents)?cents:NaN}
function formatBRLInput(value){let n=Number(value);return Number.isFinite(n)?n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}):''}
