function orderTotalCents(products,draft){return products.reduce((sum,p)=>sum+priceCents(p.price)*Number(draft.quantities[p.sku]||0),0)}

function productMatches(product,query){const terms=norm(query).split(' ').filter(Boolean),sku=norm(product.sku).replace(/ /g,''),description=norm(product.description),initials=description.split(' ').filter(Boolean).map(w=>w[0]).join('');return terms.every(term=>sku.includes(term)||description.includes(term)||initials.includes(term))}
function filterOrderProducts(query){const draft=orderDraft(),items=pricesForTable(draft.priceTable).filter(p=>p.brand===draft.brand);let shown=0;document.querySelectorAll('.order-items tr[data-product-search]').forEach(row=>{const sku=row.cells[1]?.textContent||'',description=row.cells[0]?.textContent||'';const matched=productMatches({sku,description},query);row.hidden=!matched;if(matched)shown++});const count=$('productSearchCount');if(count)count.textContent=`${shown} de ${items.length} produtos`}
function setOrderQuantity(sku,value){let d=orderDraft(),qty=Math.max(0,Math.floor(Number(value)||0));d.quantities[sku]=qty;let products=pricesForTable(d.priceTable).filter(p=>p.brand===d.brand),p=products.find(x=>x.sku===sku),cell=document.querySelector(`[data-subtotal="${CSS.escape(sku)}"]`);if(cell&&p)cell.textContent=money(priceCents(p.price)*qty/100);let total=$('orderTotal');if(total)total.textContent=money(orderTotalCents(products,d)/100)}
async function saveOrder(e){e.preventDefault();const files=[...e.target.elements.attachments.files];if(files.length&&(!s.token||!navigator.onLine))return alert('Entre no sistema e conecte-se à internet para enviar comprovantes.');if(files.length>5||files.some(f=>f.size>5*1024*1024||f.size===0||!/[.]pdf$|[.]jpe?g$|[.]png$/i.test(f.name)))return alert('Selecione até cinco arquivos PDF, JPG ou PNG de no máximo 5 MB cada.');let d=orderDraft(),products=pricesForTable(d.priceTable).filter(p=>p.brand===d.brand),items=products.map(p=>({sku:p.sku,description:p.description||'',quantity:Number(d.quantities[p.sku]||0),unitPrice:(priceCents(p.price)/100).toFixed(2)})).filter(i=>i.quantity>0);if(!d.clientId||!d.priceTable||!d.brand){alert('Selecione o cliente, a tabela de preços e a marca.');return}if(!items.length){alert('Informe a quantidade de pelo menos um produto.');return}let total=products.reduce((sum,p)=>sum+priceCents(p.price)*Number(d.quantities[p.sku]||0),0),form=new FormData(e.target),finalized=e.submitter?.value==='finalize',order={id:d.id||uid(),orderNumber:s.orders.find(x=>x.id===d.id)?.orderNumber,date:d.date,clientId:d.clientId,priceTable:d.priceTable,brand:d.brand,items,status:finalized?'Confirmado':(form.get('status')||'Pendente'),amount:total/100,user:s.user};s.orders=s.orders.filter(x=>x.id!==order.id);s.orders.push(order);const uploadSync=queue('order',order);window.currentOrder=null;window.prefillId='';if(files.length){await uploadSync;if(s.pending.some(x=>x.type==='order'&&x.data.id===order.id)){alert('Pedido salvo neste aparelho. Os comprovantes ainda não foram enviados; abra Comprovantes no pedido após sincronizar.');show('pedidos');return}try{await uploadOrderFiles(order.id,files)}catch(err){alert('Pedido salvo; falha no envio dos comprovantes: '+err.message+'. Abra Comprovantes para reenviar.')}}if(finalized){await uploadSync;if(!s.orders.find(x=>x.id===order.id)?.orderNumber){alert('Pedido salvo. O número e o PDF estarão disponíveis após a sincronização com a nuvem.');show('pedidos');return}shareOrderPDF(order.id,true)}show('pedidos')}
