async function manageOrderAttachments(id){const panel=$('orderAttachments');if(!panel||!s.token)return alert('Entre no sistema para acessar comprovantes.');panel.innerHTML='<div class="box">Carregando comprovantes…</div>';try{const response=await fetch(s.server+'/api/orders/'+encodeURIComponent(id)+'/attachments',{headers:{Authorization:'Bearer '+s.token}});if(!response.ok)throw Error('Não foi possível consultar os comprovantes.');const files=await response.json(),order=s.orders.find(x=>x.id===id),editable=['Pendente','Cancelado'].includes(order?.status);panel.innerHTML='<div class="box"><h3>Comprovantes do pedido</h3><p class="muted">Até cinco arquivos PDF, JPG ou PNG de 5 MB. Somente usuários conectados podem acessar.</p>'+files.map(f=>'<p>'+esc(f.name)+' ('+Math.ceil(f.size/1024)+' KB) <button type="button" onclick="downloadOrderAttachment(\''+esc(id)+'\',\''+esc(f.id)+'\',\''+esc(encodeURIComponent(f.name))+'\')">Baixar</button> '+(editable?'<button type="button" class="secondary" onclick="deleteOrderAttachment(\''+esc(id)+'\',\''+esc(f.id)+'\')">Excluir</button>':'')+'</p>').join('')+'<label>Adicionar comprovantes<input id="moreOrderFiles" type="file" accept=".pdf,.jpg,.jpeg,.png" multiple></label><button type="button" onclick="addOrderAttachments(\''+esc(id)+'\')">Enviar arquivos</button></div>';panel.scrollIntoView({behavior:'smooth'})}catch(err){panel.textContent=err.message}}
