function orderFileName(order){let name=(client(order.clientId).name||'cliente').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase();return `pedido-${orderLabel(order.orderNumber)}-${order.date}-${name||'cliente'}.pdf`}
function downloadBlob(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function downloadOrderPDF(id){let order=s.orders.find(x=>x.id===id);if(!order)return;if(!order.orderNumber)return alert('Aguarde a sincronização para gerar o PDF com número.');downloadBlob(orderPDFBlob(order),orderFileName(order))}
function orderShareText(order){let c=client(order.clientId),items=(order.items||[]).reduce((n,i)=>n+Number(i.quantity||0),0);return `Pedido nº ${orderLabel(order.orderNumber)} - L2 ONE\nCliente: ${c.name||'-'}\nTabela: ${order.priceTable||order.state||'-'}\nMarca: ${order.brand||'-'}\nItens: ${items}\nTotal: ${money(order.amount)}`}
async function shareOrderPDF(id,automatic=false){let order=s.orders.find(x=>x.id===id);if(!order)return;if(!order.orderNumber)return alert('Aguarde a sincronização para gerar o PDF com número.');let blob=orderPDFBlob(order),name=orderFileName(order);downloadBlob(blob,name);let file=new File([blob],name,{type:'application/pdf'}),data={title:'Pedido L2 ONE',text:orderShareText(order),files:[file]};if(navigator.share&&navigator.canShare?.(data)){try{await navigator.share(data);return}catch(err){if(err.name==='AbortError')return}}let phone=digits(client(order.clientId).phone);if(phone.length===10||phone.length===11)phone='55'+phone;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(orderShareText(order)+'\n\nO PDF foi baixado. Anexe o arquivo '+name+' nesta conversa.')}`,'_blank','noopener');if(automatic)alert('Pedido finalizado. O PDF foi salvo e o WhatsApp foi aberto para o envio.')}
async function importPrices(e){
 e.preventDefault();
 if(!s.server||!s.token)return alert('Conecte o sistema ao servidor antes de importar preços.');
 const form=new FormData(e.target),file=form.get('priceFile');
 const source=file?.size?await file.text():String(form.get('prices')||'');
 const lines=source.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),prices=[],seen=new Set();
 if(!lines.length)return alert('Selecione um arquivo ou cole a tabela de preços.');
 for(let i=0;i<lines.length;i++){
  const parts=lines[i].split(';').map(x=>x.trim());
  if(i===0&&/marca/i.test(parts[0])&&/sku/i.test(parts[1]||''))continue;
  if(parts.length!==5)return alert(`Linha ${i+1}: use Marca; SKU; Descrição; UF; Preço.`);
  let [brand,sku,description,state,value]=parts,cents=parseBRLCents(value);
  state=state.toUpperCase();
  if(!brand||!sku||!['PA','AP'].includes(state)||!Number.isFinite(cents)||cents<=0)return alert(`Linha ${i+1}: confira marca, SKU, UF e preço.`);
  const key=[brand,state,sku].join('|');
  if(seen.has(key))return alert(`Linha ${i+1}: SKU repetido para a mesma marca e UF.`);
  seen.add(key);prices.push({brand,sku,description,state,price:(cents/100).toFixed(2)});
 }
 const button=e.target.querySelector('button[type="submit"]')||e.target.querySelector('button');
 const status=$('priceImportStatus');
 if(button)button.disabled=true;
 let completed=0;
 try{
  for(let offset=0;offset<prices.length;offset+=500){
   if(status)status.textContent=`Importando ${completed} de ${prices.length} preços…`;
   const response=await fetch(s.server+'/api/prices/import',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:JSON.stringify({prices:prices.slice(offset,offset+500)})});
   const data=await response.json();
   if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Importação recusada.');
   completed+=data.imported;
  }
  if(status)status.textContent=`${completed} preços importados. Sincronizando catálogo…`;
  await sync();show('marcas');
  alert(`${completed} preço(s) importado(s) com sucesso.`);
 }catch(err){
  if(status)status.textContent=`${completed} de ${prices.length} importados. É seguro repetir o mesmo arquivo.`;
  alert('Importação interrompida: '+err.message+'. '+completed+' registros enviados; repita o mesmo arquivo para concluir.');
 }finally{if(button)button.disabled=false}
}
function saveVisit(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));const editing=!!d.id;d.id=d.id||uid();d.user=s.user;d.amount=Number(d.amount||0);s.visits=s.visits.filter(x=>x.id!==d.id);s.visits.push(d);queue('visit',d);if(d.amount>0){alert('Atendimento registrado. O pedido por valor total não foi criado: novos pedidos exigem itens e preços da tabela do estado do cliente.')}if(d.next&&!editing){let t={id:uid(),clientId:d.clientId,text:d.next,date:d.returnDate||d.date,user:s.user,status:'Aberta'};s.tasks.push(t);queue('task',t)}window.prefillId='';show('hoje')}
function editTask(id){const t=s.tasks.find(x=>x.id===id);if(!t)return;show('gestao');const f=$('taskForm');for(const [k,value] of Object.entries(t))if(f.elements[k])f.elements[k].value=value??'';f.scrollIntoView({behavior:'smooth'})}
function saveTask(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));const old=s.tasks.find(x=>x.id===d.id);d={...old,...d,id:d.id||uid(),status:old?.status||'Aberta'};s.tasks=s.tasks.filter(x=>x.id!==d.id);s.tasks.push(d);queue('task',d);show('gestao')}
function saveGoal(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.amount=parseBRLCents(d.amount)/100;if(!Number.isFinite(d.amount)||d.amount<0)return alert('Informe uma meta válida em reais.');d.id=d.month+'-'+d.user.toLowerCase().replace(/[^a-z0-9]+/g,'-');let i=s.goals.findIndex(x=>x.id===d.id);if(i<0)s.goals.push(d);else s.goals[i]=d;queue('goal',d);window.reportMonth=d.month;show('gestao')}
function commissionKey(brand){return norm(brand).replace(/ /g,'-')}
function commissionPercent(value){let str=String(value??'').trim().replace(',','.');if(!/^\d+(?:\.\d{1,2})?$/.test(str))return NaN;return Number(str)}
function saveCommissionRate(event){event.preventDefault();if(!financeAllowed())return;const form=event.target,brand=form.elements.brand.value.trim(),rate=commissionPercent(form.elements.rate.value);if(!brand||!Number.isFinite(rate)||rate<0||rate>100)return alert('Informe uma indústria e percentual entre 0 e 100, com até duas casas decimais.');const data={id:commissionKey(brand),brand,rate};s.commissionRates=s.commissionRates.filter(x=>x.id!==data.id);s.commissionRates.push(data);queue('commission_rate',data);show('gestao')}
function saveCommissionReceipt(event){event.preventDefault();if(!financeAllowed())return;const form=event.target,brand=form.elements.brand.value,month=form.elements.month.value,cents=parseBRLCents(form.elements.received.value);if(!brand||!/^\d{4}-\d{2}$/.test(month)||!Number.isSafeInteger(cents)||cents<0)return alert('Informe o mês e o valor recebido em reais.');const data={id:month+'|'+commissionKey(brand),brand,month,received:(cents/100).toFixed(2)};s.commissionReceipts=s.commissionReceipts.filter(x=>x.id!==data.id);s.commissionReceipts.push(data);queue('commission_receipt',data);show('gestao')}
function commissionPanel(month){if(!financeAllowed())return '';const brands=[...new Map([...s.prices.map(x=>x.brand),...s.orders.map(x=>x.brand),...s.commissionRates.map(x=>x.brand)].filter(Boolean).map(x=>[commissionKey(x),x])).values()].sort((a,b)=>a.localeCompare(b,'pt-BR'));const rows=brands.map(brand=>{const key=commissionKey(brand),rate=s.commissionRates.find(x=>x.id===key)?.rate,received=s.commissionReceipts.find(x=>x.id===month+'|'+key)?.received||0,billedCents=s.orders.filter(x=>x.date?.startsWith(month)&&x.status==='Faturado'&&commissionKey(x.brand)===key).reduce((sum,x)=>sum+Math.round(Number(x.amount||0)*100),0),expected=rate===undefined?null:Math.round(billedCents*Number(rate)/100);return `<tr><td>${esc(brand)}</td><td>${rate===undefined?'Não informado':esc(Number(rate).toLocaleString('pt-BR',{maximumFractionDigits:2}))+'%'}</td><td>${money(billedCents/100)}</td><td>${expected===null?'—':money(expected/100)}</td><td>${money(received)}</td><td>${expected===null?'—':money((expected-Math.round(Number(received)*100))/100)}</td></tr>`}).join('');return `<div class="box"><h3>Comissões por indústria</h3><p class="muted">Previsão calculada sobre pedidos marcados como Faturado no mês. Registre o valor efetivamente recebido para acompanhar o saldo. Ajustes, impostos e regras de liquidez não são calculados automaticamente.</p><div class="scroll"><table><tr><th>Indústria</th><th>Comissão</th><th>Faturado</th><th>Previsão</th><th>Recebido</th><th>Saldo previsto</th></tr>${rows}</table></div><form onsubmit="saveCommissionRate(event)"><div class="row"><label>Indústria<select name="brand" required><option value="">Selecione</option>${brands.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label><label>Percentual de comissão (%)<input name="rate" inputmode="decimal" placeholder="5,00" required></label></div><button>Salvar percentual</button></form><form onsubmit="saveCommissionReceipt(event)"><div class="row"><label>Indústria<select name="brand" required><option value="">Selecione</option>${brands.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label><label>Mês da comissão<input name="month" type="month" value="${esc(month)}" required></label><label>Valor recebido no mês (R$)<input name="received" inputmode="decimal" placeholder="0,00" required></label></div><button>Salvar valor recebido</button></form></div>`}
function done(id){let t=s.tasks.find(x=>x.id===id);t.status='Concluída';queue('task',t);show('hoje')}
function addRoute(id){let d=window.routeDay||today(),n=s.routes.filter(x=>x.date===d).length;if(n>=10){alert('A rota já tem 10 clientes. Retire um para adicionar outro.');return}let r={id:uid(),date:d,clientId:id,order:n+1,user:s.user};s.routes.push(r);queue('route',r);show('rota')}
function removeRoute(id){s.routes=s.routes.filter(x=>x.id!==id);queue('delete_route',{id});show('rota')}
function autoRoute(day=today(),replace=false){
 window.routeAttemptedDay=day;
 if(!['Ana Paula','Euler'].includes(s.user)){alert('A roteirização é restrita aos representantes Ana Paula e Euler.');window.routeBuilding=false;return}
 const existing=s.routes.filter(r=>r.date===day);
 if(replace){for(const r of existing){s.routes=s.routes.filter(x=>x.id!==r.id);s.pending.push({type:'delete_route',data:{id:r.id},changeId:uid()})}}
 const picks=suggestedClients(day,8);
 let order=s.routes.filter(r=>r.date===day).length;
 for(const c of picks){let r={id:uid(),date:day,clientId:c.id,order:++order,user:s.user,suggested:true,location:locationLabel(c),reason:priority(c).reason};s.routes.push(r);s.pending.push({type:'route',data:structuredClone(r),changeId:uid()})}
 window.routeBuilding=false;save();if(s.server&&navigator.onLine)sync();show('rota');
}
function changeOrder(id,status){
 const o=s.orders.find(x=>x.id===id);
 if(!o)return;
 if(!Array.isArray(o.items)||!o.items.length){alert('Pedido antigo: alteração de status indisponível até a migração para pedidos por itens.');show('pedidos');return}
 o.status=status;queue('order',o);show('pedidos')
}
async function previewClientCleanup(){const panel=$('cleanupPreview');panel.textContent='Conferindo a base…';try{const r=await fetch(s.server+'/api/admin/clients/cleanup',{headers:{Authorization:'Bearer '+s.token}});const data=await r.json();if(!r.ok)throw Error(data.detail||'Consulta recusada');panel.innerHTML='<p>Base: '+data.total+' · Fora de PA/AP: '+data.outside+' · Duplicados inequívocos: '+data.duplicates+' · Após limpeza: '+data.remaining+'.</p><p class="muted">Cadastros retirados ficam arquivados; histórico de pedidos e visitas é preservado. Lojas com endereços diferentes são mantidas.</p>'+(data.outside||data.duplicates?'<button type="button" id="applyCleanup">Aplicar limpeza da base</button>':'<p>Não há registros para retirar.</p>');const button=$('applyCleanup');if(button)button.onclick=()=>applyClientCleanup(data)}catch(err){panel.textContent=err.message}}
async function applyClientCleanup(preview){if(!confirm('Arquivar '+preview.outside+' cliente(s) fora de PA/AP e unir '+preview.duplicates+' duplicado(s) confirmado(s)?'))return;try{const r=await fetch(s.server+'/api/admin/clients/cleanup',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:JSON.stringify({previewHash:preview.previewHash})});const result=await r.json();if(!r.ok)throw Error(result.detail||'Limpeza recusada');await sync();alert('Base atualizada: '+result.remaining+' clientes PA/AP.');show('config')}catch(err){alert(err.message)}}
function exportData(){let b=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='L2_ONE_backup_'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}
async function importData(f){if(!f)return;try{let d=JSON.parse(await f.text());if(!Array.isArray(d.clients))throw Error('Arquivo inválido');if(confirm('Substituir os dados locais pelo backup?')){s={...defaults,...d,token:'',server:'',pending:[]};save();show('hoje')}}catch(e){alert(e.message)}}

function renderPasswordChange(){
 $('app').innerHTML=`<div class="box"><h2>Crie sua senha pessoal</h2><p>Olá, ${esc(s.user)}. Para liberar seu primeiro acesso, substitua a senha provisória.</p><form id="passwordChangeForm"><label>Senha provisória<input id="currentPassword" type="password" autocomplete="current-password" required></label><label>Nova senha (mínimo de 12 caracteres)<input id="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><label>Confirme a nova senha<input id="confirmPassword" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><p id="passwordChangeError" role="alert"></p><button id="passwordChangeSubmit">Salvar senha pessoal</button></form><p><button class="secondary" onclick="logout()">Sair</button></p></div>`;
 $('passwordChangeForm').onsubmit=submitPasswordChange;
}
async function submitPasswordChange(event){
 event.preventDefault();
 const currentPassword=$('currentPassword').value,newPassword=$('newPassword').value;
 const error=$('passwordChangeError'),button=$('passwordChangeSubmit');
 if(newPassword!==$('confirmPassword').value){error.textContent='As novas senhas não coincidem.';return}
 button.disabled=true;error.textContent='';
 try{
  const r=await fetch(s.server+'/api/change-password',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:JSON.stringify({currentPassword,newPassword})});
  const data=await r.json();
  if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Não foi possível alterar a senha.');
  s.token='';s.mustChangePassword=false;s.syncAt='';save();show('config');
  alert('Senha alterada. Entre novamente com sua senha pessoal.');
 }catch(e){error.textContent=e.message;button.disabled=false}
}
async function connect(){
 const user=$('who').value, server=$('server').value.replace(/\/$/,'');
 if(!server || (location.protocol==='https:' && !server.startsWith('https://'))){alert('Informe uma URL HTTPS válida.');return}
 if(s.pending.length && (user!==s.user || server!==s.server)){alert('Sincronize ou exporte o backup das alterações pendentes antes de trocar usuário ou servidor.');return}
 try{
  const r=await fetch(server+'/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user,password:$('password').value})});
  if(!r.ok)throw Error('Login não autorizado');
  const session=await r.json(), token=session.token;
  if(user!==s.user || server!==s.server){s={...defaults,user,server};}
  s.user=user;s.server=server;s.token=token;s.mustChangePassword=!!session.mustChangePassword;if(user==='Marlene')clearRestrictedCache();save();if(s.mustChangePassword){show('config');return}await sync();show('config');
 }catch(e){alert('Não foi possível conectar: '+e.message)}
}
async function adminResetPassword(event){
 event.preventDefault();const form=event.target,fields=new FormData(form),newPassword=fields.get('newPassword'),message=$('adminResetError');
 if(newPassword!==fields.get('confirmation')){message.textContent='As senhas não coincidem.';return}
 const button=form.querySelector('button[type=submit]');button.disabled=true;message.textContent='';
 try{const response=await fetch(s.server+'/api/admin/reset-my-password',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:JSON.stringify({newPassword})});const data=await response.json();if(!response.ok)throw Error(data.detail||'Não foi possível redefinir a senha.');s.token='';s.mustChangePassword=false;save();show('config');alert('Senha redefinida. Entre novamente com a nova senha em cada aparelho; as alterações locais pendentes foram preservadas.');}catch(error){message.textContent=error.message;button.disabled=false}
}
async function loadTeamAccess(){
 const panel=$('teamAccessPanel');if(!panel||s.user!=='Ana Paula'||!s.token)return;
 panel.textContent='Consultando equipe…';
 try{const response=await fetch(s.server+'/api/admin/team-access',{headers:{Authorization:'Bearer '+s.token}}),rows=await response.json();if(!response.ok)throw Error(rows.detail||'Não foi possível consultar a equipe.');panel.innerHTML=rows.filter(row=>row.user!=='Ana Paula').map(row=>`<p><b>${esc(row.user)}</b> · ${row.active?(row.mustChangePassword?'Troca de senha pendente':'Conta ativa'):'Conta inativa'} ${row.active?`<button type="button" data-user="${esc(row.user)}" onclick="resetTeamAccess(this.dataset.user)">Gerar senha provisória</button>`:''}</p>`).join('')+'<p class="muted">A senha provisória aparecerá uma única vez após a geração. Entregue-a diretamente à pessoa.</p>';}catch(error){panel.textContent=error.message}
}
async function resetTeamAccess(user){
 if(!['Euler','Laís','Marlene'].includes(user)||!confirm('Gerar uma nova senha provisória para '+user+'? A senha anterior e as sessões atuais serão invalidadas.'))return;
 const panel=$('teamAccessPanel');if(!panel)return;
 try{const response=await fetch(s.server+'/api/admin/team-access/reset',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:JSON.stringify({user})}),data=await response.json();if(!response.ok)throw Error(data.detail||'Falha ao gerar acesso.');panel.replaceChildren();const title=document.createElement('p'),password=document.createElement('code'),note=document.createElement('p');title.textContent='Senha provisória de '+data.user+': ';password.textContent=data.temporaryPassword;note.textContent='Copie agora e entregue diretamente à pessoa. Esta senha não aparecerá novamente. Ela deverá criar sua senha pessoal ao entrar.';panel.append(title,password,note);}catch(error){panel.textContent=error.message}
}
async function logout(){
 if(!confirm('Sair deste aparelho? A senha será solicitada no próximo acesso.'))return;
 if(s.pending.some(x=>['office_finance','office_budget','office_monthly_close','cash_day','cash_entry','commission_rate','commission_receipt','office_process'].some(kind=>x.type===kind||x.type==='delete_'+kind)))return alert('Sincronize as alterações financeiras pendentes antes de sair.');
 const token=s.token,server=s.server;
 if(token&&server&&navigator.onLine){try{await fetch(server+'/api/logout',{method:'POST',headers:{Authorization:'Bearer '+token}})}catch(_){}}
 s.token='';s.mustChangePassword=false;s.syncAt='';clearRestrictedCache();save();show('config');
}
async function sync(){
 if(s.mustChangePassword||syncing||!s.server||!s.token||!navigator.onLine)return;
 syncing=true;
 const batch=s.pending.slice(0,500), user=s.user, server=s.server, token=s.token;
 try{
  const r=await fetch(server+'/api/sync',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({changes:batch})});
  if(!r.ok){let detail='';try{const payload=await r.json();detail=typeof payload.detail==='string'?payload.detail:''}catch(_){}if(r.status===401){s.token='';clearRestrictedCache();save();alert('Sua sessão expirou. Entre novamente em Configurações.')}throw Error('Sincronização recusada ('+r.status+'): '+(detail||'verifique os dados enviados'))}
  const data=await r.json();
  if(user!==s.user||server!==s.server||token!==s.token)return;
  const acknowledged=new Set(batch.map(x=>x.changeId));
  s.pending=s.pending.filter(x=>!acknowledged.has(x.changeId));
  for(const name of ['clients','visits','orders','tasks','routes','goals','prices','officeProcesses','officeActions','officeCommercial','officeAdministrative','officeRituals','officeRoles','officeFinance','officeBudget','officeMonthlyClose','commissionRates','commissionReceipts','cashDays','cashEntries','whatsappTemplates'])if(Array.isArray(data[name]))s[name]=data[name];
  // Reaplica alterações criadas enquanto a solicitação estava em andamento.
  for(const change of s.pending){const name={...entityCollections,delete_whatsapp_template:'whatsappTemplates',delete_client:'clients',delete_visit:'visits',delete_order:'orders',delete_task:'tasks',delete_goal:'goals',delete_price:'prices',delete_cash_entry:'cashEntries',delete_office_process:'officeProcesses',delete_office_action:'officeActions',delete_office_commercial:'officeCommercial',delete_office_administrative:'officeAdministrative',delete_office_ritual:'officeRituals',delete_office_role:'officeRoles',delete_office_finance:'officeFinance',delete_office_budget:'officeBudget',delete_office_monthly_close:'officeMonthlyClose',delete_commission_rate:'commissionRates',delete_commission_receipt:'commissionReceipts',commission_rate:'commissionRates',commission_receipt:'commissionReceipts',client:'clients',visit:'visits',order:'orders',task:'tasks',route:'routes',delete_route:'routes',office_action:'officeActions',office_commercial:'officeCommercial',office_administrative:'officeAdministrative',office_ritual:'officeRituals',office_role:'officeRoles',office_finance:'officeFinance',office_budget:'officeBudget',office_monthly_close:'officeMonthlyClose',office_process:'officeProcesses',cash_day:'cashDays',cash_entry:'cashEntries'}[change.type];if(!name)continue;s[name]=s[name].filter(x=>(name==='prices'?(x.id||[x.brand,x.state,x.sku].join('|')):x.id)!==change.data.id);if(!change.type.startsWith('delete_'))s[name].push(change.data)}
  s.syncAt=new Date().toLocaleString('pt-BR');window.routeAttemptedDay='';save();show(tab);
 }catch(e){console.warn(e);window.lastSyncError=e.message;network();if(batch.length)alert('Os dados foram salvos neste aparelho, mas NÃO foram enviados à nuvem. '+e.message)}finally{syncing=false;if(!s.mustChangePassword&&s.pending.length&&s.server&&s.token&&navigator.onLine)setTimeout(sync,3000)}
}

let deferredInstallPrompt=null;
function appInstalled(){return window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function refreshInstallButton(){const button=$('installAppButton');if(button)button.hidden=appInstalled()||(!deferredInstallPrompt&&!/Android|iPhone|iPad|iPod/i.test(navigator.userAgent))}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;refreshInstallButton()});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;hideInstallGuide();refreshInstallButton()});
async function showInstallGuide(){if(deferredInstallPrompt){const prompt=deferredInstallPrompt;deferredInstallPrompt=null;prompt.prompt();await prompt.userChoice;refreshInstallButton();return}
 const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent),steps=$('installSteps'),guide=$('installGuide');
 if(!guide)return;
 steps.textContent=ios?'No Safari, toque em Compartilhar (quadrado com seta para cima), escolha Adicionar à Tela de Início e confirme Adicionar.':'No Chrome, toque no menu ⋮ e escolha Instalar app ou Adicionar à tela inicial.';
 guide.hidden=false;guide.querySelector('.install-close')?.focus();
}
function hideInstallGuide(){const guide=$('installGuide');if(guide)guide.hidden=true}
refreshInstallButton();
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>show(b.dataset.tab));
window.addEventListener('online',()=>{network();sync()});window.addEventListener('offline',network);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync()});setInterval(sync,30000);
(async()=>{if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});if(!s.server&&location.protocol.startsWith('http'))s.server=location.origin;save();show('hoje');sync()})();

function whatsappPhone(value){let phone=digits(value);if(phone.length===10||phone.length===11)phone='55'+phone;return /^55\d{10,11}$/.test(phone)?phone:''}
function renderWhatsapp(){
 const templates=s.whatsappTemplates||[],customers=s.clients.slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'pt-BR'));
 const orders=s.orders.filter(o=>o.orderNumber).slice().reverse();
 const currentTemplate=templates.find(x=>x.id===window.whatsappTemplateId),currentClient=customers.find(x=>x.id===window.whatsappClientId);
 return `<div class="page-heading"><div><span class="eyebrow">Relacionamento com clientes</span><h2>WhatsApp</h2><p>Organize mensagens de promoções e campanhas e envie pedidos diretamente ao contato do cliente.</p></div></div>
 <div class="box"><h3>Modelos de mensagem</h3><form id="whatsappTemplateForm"><div class="row"><label>Categoria<select name="category"><option>Promoção</option><option>Campanha</option></select></label><label>Título<input name="title" required maxlength="100" placeholder="Ex.: Oferta da semana"></label></div><label>Mensagem<textarea name="message" required maxlength="3000" rows="5" placeholder="Olá, {cliente}! Confira as novidades da {marca}."></textarea></label><p class="muted">Use {cliente} e {marca} para personalizar o texto. Os modelos são compartilhados com a equipe após a sincronização.</p><button type="submit">Salvar modelo</button></form>${templates.length?`<div class="scroll"><table><tr><th>Categoria</th><th>Modelo</th><th>Ação</th></tr>${templates.map(t=>`<tr><td>${esc(t.category)}</td><td>${esc(t.title)}</td><td><button type="button" class="secondary" onclick="selectWhatsappTemplate('${esc(t.id)}')">Selecionar</button> <button type="button" class="secondary" onclick="deleteEntity('whatsapp_template','${esc(t.id)}')">Excluir</button></td></tr>`).join('')}</table></div>`:''}</div>
 <div class="box"><h3>Enviar promoção ou campanha</h3><label>Cliente<select id="whatsappClient" onchange="window.whatsappClientId=this.value"><option value="">Selecione</option>${customers.map(c=>`<option value="${esc(c.id)}" ${c.id===currentClient?.id?'selected':''}>${esc(c.name||'Sem nome')} · ${esc(c.phone||'sem telefone')}</option>`).join('')}</select></label><label>Modelo selecionado<input id="whatsappSelectedTitle" readonly value="${esc(currentTemplate?.title||'Selecione um modelo acima')}"></label><label>Marca (opcional)<input id="whatsappBrand" placeholder="Marca desta campanha"></label><p><button type="button" onclick="sendWhatsappMessage()">Abrir conversa no WhatsApp</button></p><p class="muted">O WhatsApp abre com a mensagem pronta; confira o destinatário e toque em enviar.</p></div>
 <div class="box"><h3>Cópia do pedido</h3><label>Pedido<select id="whatsappOrder"><option value="">Selecione</option>${orders.map(o=>`<option value="${esc(o.id)}">Nº ${orderLabel(o.orderNumber)} · ${esc(client(o.clientId).name||'Cliente')} · ${esc(money(o.amount))}</option>`).join('')}</select></label><p><button type="button" onclick="sendWhatsappOrder()">Compartilhar PDF do pedido</button></p><p class="muted">No celular, escolha o WhatsApp na tela de compartilhamento. Confira a conversa antes de enviar.</p></div>`;
}
function saveWhatsappTemplate(event){event.preventDefault();const form=event.target,title=form.elements.title.value.trim(),message=form.elements.message.value.trim();if(!title||!message)return;let item={id:uid(),category:form.elements.category.value,title,message};s.whatsappTemplates.push(item);queue('whatsapp_template',item);window.whatsappTemplateId=item.id;render()}
function selectWhatsappTemplate(id){window.whatsappTemplateId=id;render()}
function sendWhatsappMessage(){const c=s.clients.find(x=>x.id===$('whatsappClient').value),t=s.whatsappTemplates.find(x=>x.id===window.whatsappTemplateId);if(!c||!t)return alert('Selecione cliente e modelo de mensagem.');const phone=whatsappPhone(c.phone);if(!phone)return alert('Cadastre um telefone brasileiro válido com DDD para este cliente.');const message=t.message.replace(/\{cliente\}/gi,c.name||'cliente').replace(/\{marca\}/gi,$('whatsappBrand').value.trim()||'L2 Representações');window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(message),'_blank','noopener')}
function sendWhatsappOrder(){let id=$('whatsappOrder').value,order=s.orders.find(x=>x.id===id);if(!order)return alert('Selecione um pedido.');if(!whatsappPhone(client(order.clientId).phone))return alert('Cadastre um telefone brasileiro válido com DDD para o cliente do pedido.');shareOrderPDF(id)}
